// Compares live agents with the approved roster file. Requires NODE_FUNCTION_ALLOW_BUILTIN to include fs.
// Approved file format: either the raw /v2/list-agents response ({ items: [...] }) or a JSON array of agent objects
// with at least agent_id, agent_name and user_modified_timestamp (save it from the first passing run into docs/evidence/).
const fs = require('fs');
const path = $env.APPROVED_AGENTS_JSON || '/data/approved-agents.json';
let approved = [];
try {
  const parsed = JSON.parse(fs.readFileSync(path, 'utf8'));
  approved = Array.isArray(parsed) ? parsed : (parsed.items || parsed.agents || []);
} catch (e) {
  return [{ json: { has_diff: true, diff: ['Could not read approved agents file at ' + path + ': ' + e.message], checked_at: new Date().toISOString() } }];
}
const live = Array.isArray($json.items) ? $json.items : (Array.isArray($json) ? $json : []);
const byId = (arr) => Object.fromEntries(arr.filter(a => a && a.agent_id).map(a => [a.agent_id, a]));
const A = byId(approved), L = byId(live);
const diff = [];
for (const id of Object.keys(L)) if (!A[id]) diff.push('UNAPPROVED agent present: ' + id + ' (' + (L[id].agent_name || '') + ')');
for (const id of Object.keys(A)) {
  const a = A[id], l = L[id];
  if (!l) { diff.push('APPROVED agent missing: ' + id + ' (' + (a.agent_name || '') + ')'); continue; }
  if (a.agent_name && l.agent_name !== a.agent_name) diff.push('RENAMED ' + id + ': "' + a.agent_name + '" -> "' + l.agent_name + '"');
  const at = Number(a.user_modified_timestamp || a.last_modification_timestamp || 0);
  const lt = Number(l.user_modified_timestamp || l.last_modification_timestamp || 0);
  if (at && lt && lt > at) diff.push('MODIFIED ' + id + ' (' + (l.agent_name || '') + '): last modified ' + new Date(lt).toISOString() + ', approved snapshot ' + new Date(at).toISOString());
}
return [{ json: { has_diff: diff.length > 0, diff, checked_at: new Date().toISOString(), live_count: live.length, approved_count: approved.length, approved_path: path } }];
